SELECT COUNT(*)
FROM emergency_event
WHERE deleted = false

      AND is_drill = FALSE


      AND create_time >= #{reqVO.startTime}


      AND create_time <= #{reqVO.endTime}


      AND event_type = #{reqVO.eventType}


      AND event_level = #{reqVO.eventLevel}


      AND status = #{reqVO.status}

SELECT COUNT(*)
FROM emergency_event
WHERE deleted = false
  AND status IN ('confirmed', 'assessing', 'handling', 'handled', 'closed')

      AND is_drill = FALSE


      AND create_time >= #{reqVO.startTime}


      AND create_time <= #{reqVO.endTime}


      AND event_type = #{reqVO.eventType}


      AND event_level = #{reqVO.eventLevel}
